// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }
    function testFuzz_property(uint256 seed1, uint256 seed2, uint256 timestamp1, uint256 timestamp2) public {
        vm.assume(timestamp1 != timestamp2);
        vm.assume(timestamp1 >= block.timestamp && timestamp2 >= block.timestamp);
        vm.assume(seed1 % 2 == 1);
        vm.assume(seed2 % 2 == 1);
        uint256 ticket = 10;
        address alice = address(0x1000);
        vm.deal(alice, 2 * ticket);

        vm.startPrank(alice);
        vm.warp(timestamp1);
        bytes32 hash1 = keccak256(abi.encodePacked(timestamp1, block.difficulty, alice));
        vm.assume(uint256(hash1) % 2 == 1);
        c.play{value: ticket}();
        uint256 potAfterFirst = c.pot();
        vm.stopPrank();

        vm.startPrank(alice);
        vm.warp(timestamp2);
        bytes32 hash2 = keccak256(abi.encodePacked(timestamp2, block.difficulty, alice));
        vm.assume(uint256(hash2) % 2 == 1);
        c.play{value: ticket}();
        uint256 potAfterSecond = c.pot();
        vm.stopPrank();

        assertTrue(potAfterSecond == 2 * ticket);
    }
}
